CREATE UNIQUE INDEX "command_audit_log_derivative_rebuild_action_uidx" ON "private"."command_audit_log" USING "btree" ("actor_user_id", (("payload" ->> 'plan_request_sha256'::"text")), (("payload" ->> 'action_request_sha256'::"text"))) WHERE (("command" = 'cmd_dataset_derivative_rebuild_plan_guarded'::"text") AND ("target_table" = ANY (ARRAY['flows'::"text", 'processes'::"text"])) AND (("payload" ->> 'record_type'::"text") = 'action'::"text"));
